{"judgments": [
 {"clause_id": "c001", "issues": []},
 {"clause_id": "c002", "issues": []},
 {"clause_id": "c003", "issues": [
   {"issue": "The Employment Period is said to end \"as provided in Section 4,\" but Section 4(a) fixes no term at all and merely lists termination events, so the \"period\" has no ascertainable end date. Section 4(b) then speaks of termination \"during the term of this Agreement,\" a term the instrument never sets.", "type": 2, "prob": 0.17}
 ]},
 {"clause_id": "c004", "issues": [
   {"issue": "Employee is made subject to \"Employee's manager or supervisor as designated by the Company from time to time,\" while Section 4(f)(iii) defines Cause by reference to failure to perform duties \"as reasonably directed by the CEO or his designees.\" Whose direction governs, and whether the Company may unilaterally change the reporting line or the position without consequence, cannot be settled from either provision alone.", "type": 2, "prob": 0.14}
 ]},
 {"clause_id": "c005", "issues": [
   {"issue": "\"Reasonable best efforts\" and \"full business time\" are qualified by a proviso allowing \"a reasonable amount of time to charitable or other similar activities,\" with no measure of what amount is reasonable and no boundary on what counts as \"similar\" to charitable. The catch-all sits directly against the full-business-time promise.", "type": 1, "prob": 0.24}
